CREATE DATABASE IF NOT EXISTS db_event_management;
USE db_event_management;
CREATE TABLE IF NOT EXISTS events (id INT AUTO_INCREMENT PRIMARY KEY,nama_event VARCHAR(150) NOT NULL,tanggal DATE NOT NULL,lokasi VARCHAR(150) NOT NULL,deskripsi TEXT,status ENUM('draft','published','closed') DEFAULT 'published',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS peserta (id INT AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(150) NOT NULL,email VARCHAR(150) NOT NULL,no_hp VARCHAR(30),event_id INT NOT NULL,status_tiket ENUM('aktif','used','batal') DEFAULT 'aktif',hadir TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reminder_logs (id INT AUTO_INCREMENT PRIMARY KEY,event_id INT NOT NULL,pesan TEXT NOT NULL,status ENUM('berhasil','gagal') DEFAULT 'berhasil',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS sertifikat (id INT AUTO_INCREMENT PRIMARY KEY,peserta_id INT NOT NULL,nomor_sertifikat VARCHAR(100) NOT NULL,status ENUM('tersedia','belum_tersedia') DEFAULT 'tersedia',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (peserta_id) REFERENCES peserta(id) ON DELETE CASCADE);
